<?php if($flash): ?><div class="alert alert-<?= $flash['type'] ?>"><?= htmlspecialchars($flash['message']) ?></div><?php endif ?><div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h3 mb-0"><?= htmlspecialchars($meta['title']) ?></h1><button class="btn btn-primary" data-bs-toggle="collapse" data-bs-target="#new-record">Add <?= rtrim($meta['title'],'s') ?></button></div><div id="new-record" class="collapse card mb-4"><div class="card-body"><form method="post" class="row g-3"><input type="hidden" name="_token" value="<?= htmlspecialchars($csrf) ?>"><?php foreach($meta['fields'] as $field=>$label): ?><div class="col-md-4"><label class="form-label"><?= $label ?></label><?php if($field==='notes'): ?><textarea class="form-control" name="<?= $field ?>"></textarea><?php else: ?><input class="form-control" name="<?= $field ?>" type="<?= str_contains($field,'date')?'date':(str_contains($field,'price')||str_contains($field,'stock')||str_contains($field,'value')||str_contains($field,'rate')||$field==='amount'?'number':'text') ?>" step="any" <?= in_array($field,['name','description'],true)?'required':'' ?>><?php endif ?></div><?php endforeach ?><div class="col-12"><button class="btn btn-success">Save</button></div></form></div></div><div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><?php foreach(array_keys($meta['fields']) as $field): ?><th><?= htmlspecialchars(ucwords(str_replace('_',' ',$field))) ?></th><?php endforeach ?><th>Created</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><?php foreach(array_keys($meta['fields']) as $field): ?><td><?= htmlspecialchars((string)($row[$field]??'')) ?></td><?php endforeach ?><td><?= htmlspecialchars((string)($row['created_at']??'')) ?></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="<?= count($meta['fields'])+1 ?>" class="text-center text-muted py-4">No records yet.</td></tr><?php endif ?></tbody></table></div></div>
